class Solution {
public:
    int count(string num1, string num2, int min_sum, int max_sum) {
        const int MOD = 1e9 + 7;
        auto count_up_to = [&](const string& s) {
            int n = s.size();
            int memo[25][405][2];
            memset(memo, -1, sizeof(memo));
            function<int(int, int, bool)> dp = [&](int idx, int cur_sum, bool is_tight) -> int {
                if (cur_sum > max_sum) return 0;
                if (idx == n) return cur_sum >= min_sum ? 1 : 0;
                if (memo[idx][cur_sum][is_tight] != -1) return memo[idx][cur_sum][is_tight];
                int limit = is_tight ? s[idx] - '0' : 9;
                long long res = 0;
                for (int d = 0; d <= limit; ++d) {
                    res = (res + dp(idx + 1, cur_sum + d, is_tight && (d == limit))) % MOD;
                }
                return memo[idx][cur_sum][is_tight] = res;
            };
            return dp(0, 0, true);
        };
        int ans = (count_up_to(num2) - count_up_to(num1) + MOD) % MOD;
        int s1 = 0;
        for (char c : num1) s1 += c - '0';
        if (s1 >= min_sum && s1 <= max_sum) ans = (ans + 1) % MOD;
        return ans;
    }
};

import java.util.Arrays;

class Solution {
    private static final int MOD = 1_000_000_007;

    private int countUpTo(String s, int minSum, int maxSum) {
        int n = s.length();
        int[][][] memo = new int[n + 1][maxSum + 1][2];
        for (int[][] a : memo) {
            for (int[] b : a) Arrays.fill(b, -1);
        }
        return dfs(s, 0, 0, true, minSum, maxSum, memo);
    }

    private int dfs(String s, int idx, int curSum, boolean isTight, int minSum, int maxSum, int[][][] memo) {
        if (curSum > maxSum) return 0;
        if (idx == s.length()) return curSum >= minSum ? 1 : 0;
        int tightIdx = isTight ? 1 : 0;
        if (memo[idx][curSum][tightIdx] != -1) return memo[idx][curSum][tightIdx];
        int limit = isTight ? s.charAt(idx) - '0' : 9;
        long res = 0;
        for (int d = 0; d <= limit; d++) {
            res = (res + dfs(s, idx + 1, curSum + d, isTight && (d == limit), minSum, maxSum, memo)) % MOD;
        }
        return memo[idx][curSum][tightIdx] = (int) res;
    }

    public int count(String num1, String num2, int min_sum, int max_sum) {
        int ans = (countUpTo(num2, min_sum, max_sum) - countUpTo(num1, min_sum, max_sum) + MOD) % MOD;
        int s1 = 0;
        for (int i = 0; i < num1.length(); i++) s1 += num1.charAt(i) - '0';
        if (s1 >= min_sum && s1 <= max_sum) ans = (ans + 1) % MOD;
        return ans;
    }
}

var count = function(num1, num2, min_sum, max_sum) {
    const MOD = 1000000007n;
    function countUpTo(s) {
        const n = s.length;
        const memo = new Map();
        function dp(idx, curSum, isTight) {
            if (curSum > max_sum) return 0n;
            if (idx === n) return curSum >= min_sum ? 1n : 0n;
            const key = `${idx},${curSum},${isTight ? 1 : 0}`;
            if (memo.has(key)) return memo.get(key);
            const limit = isTight ? Number(s[idx]) : 9;
            let res = 0n;
            for (let d = 0; d <= limit; d++) {
                res = (res + dp(idx + 1, curSum + d, isTight && (d === limit))) % MOD;
            }
            memo.set(key, res);
            return res;
        }
        return dp(0, 0, true);
    }
    let ans = (countUpTo(num2) - countUpTo(num1) + MOD) % MOD;
    let s1 = 0;
    for (let i = 0; i < num1.length; i++) s1 += Number(num1[i]);
    if (s1 >= min_sum && s1 <= max_sum) ans = (ans + 1n) % MOD;
    return Number(ans);
};
